import{_ as n,o as t,c as r,ah as a}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Social Media Cheat-Sheet: Das System herausfordern","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/social-media-cheat-sheet.md","filePath":"recherche/social-media-cheat-sheet.md"}'),s={name:"recherche/social-media-cheat-sheet.md"};function i(o,e,l,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="social-media-cheat-sheet-das-system-herausfordern" tabindex="-1">Social Media Cheat-Sheet: Das System herausfordern <a class="header-anchor" href="#social-media-cheat-sheet-das-system-herausfordern" aria-label="Permalink to &quot;Social Media Cheat-Sheet: Das System herausfordern&quot;">​</a></h1><p><strong>Die Kunst der Intervention – und wie wir darauf antworten.</strong></p><p>Im Rahmen unseres Mockumentary-Projekts <em>„Das Horten-Mysterium“</em> dokumentieren wir nicht nur die Machtstrukturen, sondern treten auch in den Dialog mit den Akteuren der aktuellen Politik. Hier findest du eine Sammlung von pointierten, satirischen und faktenbasierten Antworten, die speziell auf die Verteidigungslinien von ÖVP und FPÖ zugeschnitten sind.</p><hr><h2 id="🏛️-fokus-ovp-thema-postenschacher-„burgeranliegen" tabindex="-1">🏛️ Fokus: ÖVP (Thema: Postenschacher / „Bürgeranliegen“) <a class="header-anchor" href="#🏛️-fokus-ovp-thema-postenschacher-„burgeranliegen" aria-label="Permalink to &quot;🏛️ Fokus: ÖVP (Thema: Postenschacher / „Bürgeranliegen“)&quot;">​</a></h2><p><strong>Wenn sie sagen:</strong> <em>„Ich setze mich nur für die Region ein / Das war ein normales Bürgeranliegen.“</em></p><ul><li><strong>Antwort 1:</strong> „Spannend. Seit wann ist eine 98-Punkte-Qualifikation ein &#39;Bürgeranliegen&#39;, das man mit 62 Punkten &#39;optimieren&#39; muss? Frage für eine Freundin namens Christa Scharf. #Postenschacher“</li><li><strong>Antwort 2:</strong> „Jede SMS ist ein Punkt im Mosaik. Wir nennen es den <strong>Pointillismus der Macht</strong>. Aus der Ferne sieht man das ganze Bild der Korruption, aus der Nähe sind es &#39;nur Gefallen&#39;. #HortenMysterium“</li></ul><p><strong>Wenn sie sagen:</strong> <em>„Die Justiz ist politisiert / Wir sind Opfer einer Jagdgesellschaft.“</em></p><ul><li><strong>Antwort 3:</strong> „Wer den Rechtsstaat zur &#39;Jagdgesellschaft&#39; erklärt, hat meistens Angst vor den Fakten. Ein 98-Punkte-Hearing lügt nicht, SMS auch nicht. #WKStA“</li></ul><hr><h2 id="🦅-fokus-fpo-thema-rosenkranz-u-ausschuss" tabindex="-1">🦅 Fokus: FPÖ (Thema: Rosenkranz / U-Ausschuss) <a class="header-anchor" href="#🦅-fokus-fpo-thema-rosenkranz-u-ausschuss" aria-label="Permalink to &quot;🦅 Fokus: FPÖ (Thema: Rosenkranz / U-Ausschuss)&quot;">​</a></h2><p><strong>Wenn sie sagen:</strong> <em>„Wir schützen die Demokratie / Kampf gegen das System.“</em></p><ul><li><strong>Antwort 4:</strong> „Demokratie schützen, indem man U-Ausschüsse mit Parteiloyalität statt Objektivität führt? Das ist kein Schutz, das ist eine Einmauerung der Wahrheit. #Rosenkranz“</li></ul><p><strong>Wenn sie sagen:</strong> <em>„Alles Lügen der Systemmedien.“</em></p><ul><li><strong>Antwort 5:</strong> „Wenn Fakten (wie Bankauszüge und Chats) zu &#39;Lügen&#39; werden, ist das Drehbuch der Post-Wahrheit fertig. Wir verfilmen es gerade als Mockumentary. #HortenMysterium“</li></ul><hr><h2 id="🎭-universelle-mockumentary-promos" tabindex="-1">🎭 Universelle Mockumentary-Promos <a class="header-anchor" href="#🎭-universelle-mockumentary-promos" aria-label="Permalink to &quot;🎭 Universelle Mockumentary-Promos&quot;">​</a></h2><p>Nutze diese Antworten, um auf unser Projekt aufmerksam zu machen:</p><ul><li>„Danke für diesen Live-Content! Das passt perfekt in Szene 42 (&#39;Die Ästhetik der Kleinigkeit&#39;). Wir filmen das gerade nach. #HortenMysterium“</li><li>„Ist das schon die offizielle Verteidigung oder nur ein Teaser für unseren Film? Die Ähnlichkeiten zur Fiktion sind rein systemisch. #PointillismusDesGeldes“</li></ul><hr><p><strong>Hilf mit, das Licht auf die Schattenseiten der Macht zu werfen.</strong> Teile diese Antworten und verlinke auf:</p><ul><li><a href="https://dokfilm.pages.dev/" target="_blank" rel="noreferrer">https://dokfilm.pages.dev/</a> (Cloudflare)</li><li><a href="https://hadawig.github.io/dokfilm" target="_blank" rel="noreferrer">https://hadawig.github.io/dokfilm</a> (GitHub)</li><li><a href="https://www.youtube.com/@VoltiSodala-p6p" target="_blank" rel="noreferrer">YouTube-Kanal</a></li></ul>',22)])])}const g=n(s,[["render",i]]);export{c as __pageData,g as default};
